/**
 * TabManager — generic, reusable tab panel system.
 *
 * Both the main studio bottom panel and the GDS viewer console
 * instantiate a TabManager to get consistent tab behaviour:
 *   • addTab(id, label, contentEl, options?)
 *   • switchTo(id)
 *   • removeTab(id)
 *   • getActive() → tab id
 *
 * Usage (main panel):
 *   const tm = new TabManager('terminal-header', 'terminal-body');
 *   tm.addTab('terminal', 'Terminal', xtermPanel, { active: true });
 *   tm.addTab('output',   'Output',   outputPanel);
 *
 * Usage (viewer console):
 *   const tm = new TabManager('console-header', 'console-body');
 *   tm.addTab('source', 'Source', sourcePanel, { active: true });
 *   tm.addTab('info',   'Info',   infoPanel);
 */

export interface TabOptions {
  /** Start as the active tab (only one should be true) */
  active?: boolean;
  /** Optional callback when this tab becomes visible */
  onActivate?: () => void;
  /** Optional close handler — if provided, tab gets an × button */
  onClose?: () => void;
  /** Icon character to show before label (emoji or symbol) */
  icon?: string;
}

interface TabEntry {
  id: string;
  label: string;
  contentEl: HTMLElement;
  onActivate?: () => void;
  onClose?: () => void;
  icon?: string;
  btnEl: HTMLElement;
}

interface AvailableTab {
  id: string;
  label: string;
  icon?: string;
  /** Factory that creates the content element and returns it + optional callbacks */
  factory: () => { el: HTMLElement; onActivate?: () => void; onClose?: () => void };
}

export class TabManager {
  private headerEl: HTMLElement;
  private bodyEl: HTMLElement;
  private tabContainer: HTMLElement;
  private tabs = new Map<string, TabEntry>();
  private availableTabs = new Map<string, AvailableTab>();
  private addBtn: HTMLElement | null = null;
  private addDropdown: HTMLElement | null = null;
  private activeTabId: string | null = null;

  constructor(headerId: string, bodyId: string) {
    this.headerEl = document.getElementById(headerId)!;
    this.bodyEl = document.getElementById(bodyId)!;

    // Find or create the tab-button container span inside the header
    this.tabContainer = this.headerEl.querySelector('.tab-bar') as HTMLElement;
    if (!this.tabContainer) {
      this.tabContainer = document.createElement('span');
      this.tabContainer.className = 'tab-bar';
      this.tabContainer.style.cssText = 'display:flex;align-items:center;gap:2px;';
      // Insert as first child of header
      this.headerEl.insertBefore(this.tabContainer, this.headerEl.firstChild);
    }
  }

  /**
   * Register a new tab.
   * @param id        Unique tab identifier (used as data-tab attribute)
   * @param label     Human-readable label shown on the tab button
   * @param contentEl The DOM element shown when this tab is active
   * @param opts      Optional: active, onActivate, onClose
   */
  addTab(id: string, label: string, contentEl: HTMLElement, opts?: TabOptions): void {
    if (this.tabs.has(id)) {
      console.warn(`TabManager: tab "${id}" already exists, skipping`);
      return;
    }

    // Create tab button
    const btn = document.createElement('span');
    btn.className = 'panel-tab-btn';
    btn.setAttribute('data-tab', id);

    // Icon + label
    if (opts?.icon) {
      const iconSpan = document.createElement('span');
      iconSpan.textContent = opts.icon;
      iconSpan.style.cssText = 'font-size:13px;line-height:1;';
      btn.appendChild(iconSpan);
    }
    const labelSpan = document.createElement('span');
    labelSpan.textContent = label;
    btn.appendChild(labelSpan);

    // Close button — always shown so user can close any tab
    const closeBtn = document.createElement('span');
    closeBtn.className = 'panel-tab-close';
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (opts?.onClose) {
        opts.onClose();
      } else {
        // Remove tab and make it re-addable via "+"
        this.removeTab(id);
        // If not already an available tab, register it so it shows in "+"
        if (!this.availableTabs.has(id)) {
          this.availableTabs.set(id, {
            id,
            label,
            icon: opts?.icon,
            factory: () => ({ el: contentEl }),
          });
        }
        this.refreshAddMenu();
      }
    });
    btn.appendChild(closeBtn);

    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.switchTo(id);
    });

    // Insert before the "+" button if it exists
    if (this.addBtn && this.addBtn.parentNode === this.tabContainer) {
      this.tabContainer.insertBefore(btn, this.addBtn);
    } else {
      this.tabContainer.appendChild(btn);
    }

    const entry: TabEntry = {
      id,
      label,
      contentEl,
      onActivate: opts?.onActivate,
      onClose: opts?.onClose,
      icon: opts?.icon,
      btnEl: btn,
    };
    this.tabs.set(id, entry);

    // Hide all panels initially, unless it's the active tab
    contentEl.style.display = 'none';

    if (opts?.active) {
      this.switchTo(id);
    }

    this.refreshAddMenu();
  }

  /**
   * Switch to a tab by id.
   */
  switchTo(id: string): void {
    const target = this.tabs.get(id);
    if (!target) return;

    this.activeTabId = id;

    for (const [tabId, entry] of this.tabs) {
      const isActive = tabId === id;
      entry.btnEl.classList.toggle('active', isActive);
      entry.contentEl.style.display = isActive ? '' : 'none';
    }

    target.onActivate?.();
  }

  /**
   * Remove a tab by id.
   */
  removeTab(id: string): void {
    const entry = this.tabs.get(id);
    if (!entry) return;

    entry.btnEl.remove();
    entry.contentEl.style.display = 'none';
    // If dynamically added, remove the content element from DOM
    if (this.availableTabs.has(id)) {
      entry.contentEl.remove();
    }

    this.tabs.delete(id);

    // If we removed the active tab, switch to the first remaining one
    if (this.activeTabId === id) {
      const first = this.tabs.values().next().value;
      if (first) {
        this.switchTo(first.id);
      } else {
        this.activeTabId = null;
      }
    }

    this.refreshAddMenu();
  }

  /**
   * Get the active tab id.
   */
  getActive(): string | null {
    return this.activeTabId;
  }

  /**
   * Register a tab as "available" — it will show in the "+" dropdown
   * and can be dynamically added by the user.
   */
  addAvailableTab(id: string, label: string, factory: AvailableTab['factory'], icon?: string): void {
    this.availableTabs.set(id, { id, label, icon, factory });
    // Lazily create the "+" button on first available tab
    this.setupAddButton();
    this.refreshAddMenu();
  }

  /**
   * Create the "+" button and dropdown if not already created.
   */
  private setupAddButton(): void {
    if (this.addBtn) return;

    this.addBtn = document.createElement('span');
    this.addBtn.className = 'panel-tab-add-btn';
    this.addBtn.textContent = '+';
    this.addBtn.title = 'Add tab';
    this.addBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleAddDropdown();
    });
    this.tabContainer.appendChild(this.addBtn);

    // Close dropdown on outside click
    document.addEventListener('click', (e) => {
      if (this.addDropdown && !this.addDropdown.contains(e.target as Node) && e.target !== this.addBtn) {
        this.hideAddDropdown();
      }
    });
  }

  private toggleAddDropdown(): void {
    if (this.addDropdown && this.addDropdown.style.display !== 'none') {
      this.hideAddDropdown();
    } else {
      this.showAddDropdown();
    }
  }

  private showAddDropdown(): void {
    if (!this.addDropdown) {
      this.addDropdown = document.createElement('div');
      this.addDropdown.className = 'panel-tab-add-dropdown';
      document.body.appendChild(this.addDropdown);
    }
    this.refreshAddMenu();

    // Position below the "+" button
    if (this.addBtn) {
      const rect = this.addBtn.getBoundingClientRect();
      this.addDropdown.style.position = 'fixed';
      this.addDropdown.style.top = `${rect.bottom + 2}px`;
      this.addDropdown.style.left = `${rect.left}px`;
    }
    this.addDropdown.style.display = 'block';
  }

  private hideAddDropdown(): void {
    if (this.addDropdown) {
      this.addDropdown.style.display = 'none';
    }
  }

  /**
   * Rebuild the dropdown menu items based on currently available tabs.
   */
  private refreshAddMenu(): void {
    if (!this.addDropdown) return;

    // Find tabs that are available but not yet added
    const items: AvailableTab[] = [];
    for (const [id, tab] of this.availableTabs) {
      if (!this.tabs.has(id)) {
        items.push(tab);
      }
    }

    this.addDropdown.innerHTML = '';

    if (items.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'panel-tab-add-empty';
      empty.textContent = 'All tabs added';
      this.addDropdown.appendChild(empty);
      // Hide the "+" button if nothing available
      if (this.addBtn) this.addBtn.style.display = 'none';
      return;
    }

    // Show "+" button
    if (this.addBtn) this.addBtn.style.display = '';

    for (const item of items) {
      const opt = document.createElement('div');
      opt.className = 'panel-tab-add-option';
      const label = document.createElement('span');
      if (item.icon) {
        const iconSpan = document.createElement('span');
        iconSpan.textContent = item.icon + ' ';
        iconSpan.style.cssText = 'font-size:12px;';
        label.appendChild(iconSpan);
      }
      const textSpan = document.createElement('span');
      textSpan.textContent = item.label;
      label.appendChild(textSpan);
      opt.appendChild(label);

      opt.addEventListener('click', (e) => {
        e.stopPropagation();
        this.addAvailableTabAsActive(item.id);
        this.hideAddDropdown();
      });
      this.addDropdown.appendChild(opt);
    }
  }

  /**
   * Instantiate an available tab and add it as active.
   */
  private addAvailableTabAsActive(id: string): void {
    const available = this.availableTabs.get(id);
    if (!available) return;

    const { el, onActivate, onClose } = available.factory();

    // If the tab was previously removed, its contentEl may be gone — create fresh
    this.bodyEl.appendChild(el);

    this.addTab(id, available.label, el, {
      active: true,
      onActivate,
      onClose: onClose || (() => {
        // Default close: remove tab and show in "+" again
        this.removeTab(id);
        this.refreshAddMenu();
      }),
      icon: available.icon,
    });
  }

  /**
   * Get the TabManager's header element (for positioning controls like settings).
   */
  getHeader(): HTMLElement {
    return this.headerEl;
  }

  /**
   * Get the tab container element (for inserting elements after the tabs).
   */
  getTabBar(): HTMLElement {
    return this.tabContainer;
  }
}

// Expose globally for IIFE bundling
declare global {
  interface Window {
    TabManager: typeof TabManager;
  }
}
window.TabManager = TabManager;
